import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Welche Datenpunkte hat eine ESPHome-Lampe?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/03.referenz/03.licht.md"},"headers":[],"relativePath":"de/adapter/esphome/referenz/licht.md","filePath":"de/adapter/esphome/referenz/licht.md","lastUpdated":1795571670000}'),d={name:"de/adapter/esphome/referenz/licht.md"};function s(r,e,h,l,o,c){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="welche-datenpunkte-hat-eine-esphome-lampe" tabindex="-1">Welche Datenpunkte hat eine ESPHome-Lampe? <a class="header-anchor" href="#welche-datenpunkte-hat-eine-esphome-lampe" aria-label="Permalink to &quot;Welche Datenpunkte hat eine ESPHome-Lampe?&quot;">​</a></h1><p><a id="datapoints-rgb-rgbw-lamp-have"></a></p><h2 id="welche-datenpunkte-hat-eine-rgb-rgbw-lampe-und-welche-werte-erwartet-sie" tabindex="-1">Welche Datenpunkte hat eine RGB/RGBW-Lampe und welche Werte erwartet sie? <a class="header-anchor" href="#welche-datenpunkte-hat-eine-rgb-rgbw-lampe-und-welche-werte-erwartet-sie" aria-label="Permalink to &quot;Welche Datenpunkte hat eine RGB/RGBW-Lampe und welche Werte erwartet sie?&quot;">​</a></h2><p>Eine Lampe hat unter <code>esphome.0.&lt;Gerät&gt;.Light.&lt;Schlüssel&gt;</code> je einen Datenpunkt für Ein/Aus, Helligkeit, Farbkanäle, Farbtemperatur, Effekt und Hex-Farbe. Helligkeit und Farbkanäle schreibst du als Zahl von 0 bis 255, die Hex-Farbe als <code>#rrggbb</code>.</p><h3 id="die-datenpunkte" tabindex="-1">Die Datenpunkte <a class="header-anchor" href="#die-datenpunkte" aria-label="Permalink to &quot;Die Datenpunkte&quot;">​</a></h3><p>Es gibt nur die Werte, die die Lampe meldet. Eine reine Ein/Aus-Lampe hat deshalb weniger Datenpunkte als eine RGBW-Lampe.</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Werte</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>state</code></td><td><code>true</code> / <code>false</code></td><td>an oder aus</td></tr><tr><td><code>brightness</code></td><td>0 bis 255</td><td>Gesamthelligkeit</td></tr><tr><td><code>red</code>, <code>green</code>, <code>blue</code></td><td>je 0 bis 255</td><td>Farbkanäle</td></tr><tr><td><code>white</code></td><td>0 bis 255</td><td>Weißkanal, nur bei RGBW</td></tr><tr><td><code>colorBrightness</code></td><td>0 bis 255</td><td>Helligkeit des Farbanteils</td></tr><tr><td><code>coldWhite</code>, <code>warmWhite</code></td><td>je 0 bis 255</td><td>Kalt- und Warmweiß</td></tr><tr><td><code>colorHEX</code></td><td>z. B. <code>#ff6600</code> oder <code>#f60</code></td><td>Farbe als Hex-Wert, nur bei Lampen mit Rot, Grün und Blau</td></tr><tr><td><code>colorTemperature</code></td><td>Zahl</td><td>Farbtemperatur in derselben 0-bis-255-Skala wie die Helligkeit, nicht in Kelvin oder Mired</td></tr><tr><td><code>colorMode</code></td><td>Zahl</td><td>Farbmodus von ESPHome, z. B. <code>35</code> für RGB</td></tr><tr><td><code>effect</code></td><td>Text</td><td>Name des Lichteffekts aus der YAML</td></tr><tr><td><code>transitionLength</code></td><td>Millisekunden</td><td>Übergangsdauer, geht mit jedem Befehl mit</td></tr><tr><td><code>config.rgbAutoWhite</code></td><td><code>true</code> / <code>false</code></td><td>nur bei RGBW: <code>#ffffff</code> schaltet auf den Weißkanal</td></tr></tbody></table><p>Ein ungültiger Hex-Wert wird ohne Meldung verworfen, die Lampe bleibt dann wie sie ist.</p><h3 id="so-schaltest-du-eine-lampe" tabindex="-1">So schaltest du eine Lampe <a class="header-anchor" href="#so-schaltest-du-eine-lampe" aria-label="Permalink to &quot;So schaltest du eine Lampe&quot;">​</a></h3><ol><li>Öffne im Admin den Tab „Objekte“ und dort <code>esphome.0.&lt;Gerät&gt;.Light.&lt;Schlüssel&gt;</code>.</li><li>Schreib einen Datenpunkt, z. B. <code>brightness</code> auf <code>128</code> oder <code>colorHEX</code> auf <code>#ff6600</code>.</li><li>Der Adapter schickt einen vollständigen Lichtbefehl. Meldet die Lampe ihren neuen Zustand, steht der Wert bestätigt (<code>ack = true</code>) im Datenpunkt.</li></ol><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;Gerät&gt;.Light.&lt;Schlüssel&gt;.state&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;Gerät&gt;.Light.&lt;Schlüssel&gt;.colorHEX&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#ff6600&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Der Befehl enthält immer Ein/Aus, Übergangsdauer und die zuletzt bekannten Werte, aber nur die, die die Lampe laut ihren Farbmodi kann. Einen Effekt schickt der Adapter nur, wenn <code>effect</code> nicht leer ist.</p><p><strong>Siehe auch:</strong> <a href="#transition-length-flash-length-light">Übergangsdauer und Flash-Länge</a> · <a href="#select-light-effect-iobroker">Lichteffekt auswählen</a> · <a href="./../anleitungen/automatisieren#use-white-channel-rgbw-lamp">Weißkanal automatisch nutzen</a> · <a href="./datenpunkte#command-acknowledged-ack-happens-offline">Wann ein Befehl als bestätigt gilt</a></p><p><a id="transition-length-flash-length-light"></a></p><h2 id="wie-setze-ich-ubergangsdauer-und-flash-lange-einer-lampe" tabindex="-1">Wie setze ich Übergangsdauer und Flash-Länge einer Lampe? <a class="header-anchor" href="#wie-setze-ich-ubergangsdauer-und-flash-lange-einer-lampe" aria-label="Permalink to &quot;Wie setze ich Übergangsdauer und Flash-Länge einer Lampe?&quot;">​</a></h2><p>Die Übergangsdauer setzt du im Datenpunkt <code>esphome.0.&lt;Gerät&gt;.Light.&lt;Schlüssel&gt;.transitionLength</code>, in Millisekunden. Standard ist <code>0</code>. Es gibt ihn bei Lampen mit Helligkeit oder Farbe.</p><p>Der Wert geht mit jedem Lichtbefehl mit, bis du ihn änderst, auch nach einem Neustart. Schreibst du nur <code>transitionLength</code>, schickt der Adapter einen Lichtbefehl mit den aktuellen Werten.</p><p>Eine Flash-Länge bietet der Adapter nicht an. Brauchst du ein Blinken, leg in der YAML einen Effekt an, z. B. <code>strobe</code>, und wähl ihn über <code>effect</code>.</p><p><strong>Siehe auch:</strong> <a href="#select-light-effect-iobroker">Lichteffekt auswählen</a></p><p><a id="select-light-effect-iobroker"></a></p><h2 id="wie-wahle-ich-einen-lichteffekt-aus-iobroker-aus" tabindex="-1">Wie wähle ich einen Lichteffekt aus ioBroker aus? <a class="header-anchor" href="#wie-wahle-ich-einen-lichteffekt-aus-iobroker-aus" aria-label="Permalink to &quot;Wie wähle ich einen Lichteffekt aus ioBroker aus?&quot;">​</a></h2><p>Schreib den Namen des Effekts in <code>esphome.0.&lt;Gerät&gt;.Light.&lt;Schlüssel&gt;.effect</code>, genau so, wie er in der YAML unter <code>effects:</code> steht. Der Adapter schickt ihn mit dem nächsten Lichtbefehl.</p><p>Eine Auswahlliste gibt es nicht. Welche Effekte die Lampe kennt, siehst du in der YAML oder, bei eingeschalteten Konfigurationszuständen, in ihrem <code>config</code>-Ordner. Einen leeren Wert schickt der Adapter nicht. Zum Beenden des Effekts schreibst du <code>None</code>.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;Gerät&gt;.Light.&lt;Schlüssel&gt;.effect&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Rainbow&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><strong>Siehe auch:</strong> <a href="#datapoints-rgb-rgbw-lamp-have">Datenpunkte einer Lampe</a></p>`,25)])])}const k=t(d,[["render",s]]);export{u as __pageData,k as default};
